/**
 * Offline dictionary backed by ECDICT (MIT, https://github.com/skywind3000/ECDICT).
 *
 * The SQLite file is generated by `npm run dict:import` and is optional: when it
 * is missing, every caller falls back to the small built-in glossary.
 */
import { existsSync } from 'node:fs';
import path from 'node:path';
import { DatabaseSync } from 'node:sqlite';
import { normalizeWord } from './text';

export type DictEntry = {
  word: string;
  display: string;
  phonetic?: string;
  definition?: string;
  translation?: string;
  pos?: string;
  collins?: number;
  oxford?: number;
  tag?: string;
  bnc?: number;
  frq?: number;
};

type DictRow = {
  word: string;
  display: string;
  phonetic: string | null;
  definition: string | null;
  translation: string | null;
  pos: string | null;
  collins: number | null;
  oxford: number | null;
  tag: string | null;
  bnc: number | null;
  frq: number | null;
};

const CACHE_LIMIT = 8000;
const cache = new Map<string, DictEntry | null>();
const statements = new Map<string, { get: (...params: unknown[]) => unknown }>();

let connectionState: DatabaseSync | null | undefined;

export function dictDbPath(): string {
  return path.resolve(process.cwd(), process.env.DICT_DB_PATH || './data/ecdict.db');
}

export function dictionaryReady(): boolean {
  return getConnection() !== null;
}

function getConnection(): DatabaseSync | null {
  if (connectionState !== undefined) return connectionState;

  const file = dictDbPath();
  if (!existsSync(file)) {
    connectionState = null;
    return null;
  }

  try {
    const db = new DatabaseSync(file);
    db.exec('PRAGMA query_only = ON;');
    connectionState = db;
  } catch (error) {
    console.warn(`[dict] failed to open ${file}:`, (error as Error).message);
    connectionState = null;
  }
  return connectionState;
}

function statement(sql: string) {
  const cached = statements.get(sql);
  if (cached) return cached;
  const db = getConnection();
  if (!db) return null;
  const prepared = db.prepare(sql) as unknown as { get: (...params: unknown[]) => unknown };
  statements.set(sql, prepared);
  return prepared;
}

const SELECT_ONE =
  'SELECT word, display, phonetic, definition, translation, pos, collins, oxford, tag, bnc, frq FROM dict WHERE word = ? LIMIT 1';

function queryWord(word: string): DictEntry | null {
  const stmt = statement(SELECT_ONE);
  if (!stmt) return null;

  try {
    const row = stmt.get(word) as DictRow | undefined;
    if (!row) return null;
    return {
      word: row.word,
      display: row.display,
      phonetic: row.phonetic ?? undefined,
      definition: row.definition ?? undefined,
      translation: row.translation ?? undefined,
      pos: row.pos ?? undefined,
      collins: row.collins ?? undefined,
      oxford: row.oxford ?? undefined,
      tag: row.tag ?? undefined,
      bnc: row.bnc ?? undefined,
      frq: row.frq ?? undefined,
    };
  } catch {
    return null;
  }
}

/** Candidate base forms for a possibly inflected token. */
function baseForms(word: string): string[] {
  const forms = new Set<string>([word]);

  const add = (form: string) => {
    if (form.length >= 2) forms.add(form);
  };

  if (word.endsWith('ies') || word.endsWith('ied')) add(`${word.slice(0, -3)}y`);
  if (word.endsWith('es')) add(word.slice(0, -2));
  if (word.endsWith('s') && !word.endsWith('ss')) add(word.slice(0, -1));
  if (word.endsWith('ing')) {
    const stem = word.slice(0, -3);
    add(stem);
    add(`${stem}e`);
    if (/([bdfglmnprt])\1$/.test(stem)) add(stem.slice(0, -1));
  }
  if (word.endsWith('ed')) {
    const stem = word.slice(0, -2);
    add(stem);
    add(`${stem}e`);
    if (/([bdfglmnprt])\1$/.test(stem)) add(stem.slice(0, -1));
  }
  if (word.endsWith('ly')) {
    add(word.slice(0, -2));
    add(`${word.slice(0, -2)}le`);
  }
  if (word.endsWith('er') || word.endsWith('est')) {
    add(word.replace(/(er|est)$/, ''));
    add(word.replace(/(er|est)$/, 'e'));
  }

  return Array.from(forms);
}

export function dictLookup(raw: string): DictEntry | null {
  const word = normalizeWord(raw);
  if (!word) return null;

  const cached = cache.get(word);
  if (cached !== undefined) return cached;

  let entry: DictEntry | null = null;
  for (const form of baseForms(word)) {
    entry = queryWord(form);
    if (entry) break;
  }

  if (cache.size >= CACHE_LIMIT) cache.clear();
  cache.set(word, entry);
  return entry;
}

/** Clears the memo cache (used by tests after re-importing the dictionary). */
export function resetDictionaryCache(): void {
  cache.clear();
  statements.clear();
  connectionState = undefined;
}
